CREATE TABLE IF NOT EXISTS streams(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL, name TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, sha256 TEXT, complete INTEGER NOT NULL DEFAULT 0, legacy_preview_only INTEGER NOT NULL DEFAULT 0, UNIQUE(operation_id,name));
CREATE TABLE IF NOT EXISTS chunks(stream_id TEXT NOT NULL REFERENCES streams(id), seq INTEGER NOT NULL, raw_size INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(stream_id,seq));
CREATE TABLE IF NOT EXISTS contents(id TEXT PRIMARY KEY, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL UNIQUE, complete INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS content_chunks(content_id TEXT NOT NULL REFERENCES contents(id) ON DELETE CASCADE, seq INTEGER NOT NULL, raw_size INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(content_id,seq));
